let win = totimespan({Window});
let src = SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | where Severity in ({SeverityFilter});
let total    = toscalar(src | count);
let closed   = toscalar(src | where Status == 'Closed' | count);
let newState = toscalar(src | where Status == 'New' | count);
let closureRate = todouble(coalesce(closed, 0)) / todouble(iff(total == 0, 1, total)) * 100.0;
let rh = SentinelHealth | where TimeGenerated > ago(7d) | where SentinelResourceType == 'Analytics Rule' | summarize arg_max(TimeGenerated, *) by SentinelResourceId;
let rulesTotal   = toscalar(rh | count);
let rulesHealthy = toscalar(rh | where Status == 'Success' | count);
let healthPct = todouble(coalesce(rulesHealthy, 0)) / todouble(iff(rulesTotal == 0, 1, rulesTotal)) * 100.0;
let alertsWin = SecurityAlert | where TimeGenerated > ago(win) | where AlertSeverity in ({SeverityFilter});
let techniques = toscalar(alertsWin | extend Tech = extract_all(@'(T\d{4}(?:\.\d{3})?)', tostring(Techniques)) | mv-expand Tech | where isnotempty(Tech) | summarize dcount(tostring(Tech)));
let mitreScore = todouble(coalesce(techniques, 0)) / 201.0 * 100.0;
let cr = todouble(coalesce(closureRate, 0.0));
let hp = todouble(coalesce(healthPct, 0.0));
let ms = todouble(coalesce(mitreScore, 0.0));
let score = toint(round((cr + hp + ms) / 3.0, 0));
print Metric='Overall Posture Score', Value=tolong(score), Subtitle=strcat('Closure ', tostring(toint(round(cr,0))), '% · Rules healthy ', tostring(toint(round(hp,0))), '% · MITRE ', tostring(toint(round(ms,0))), '%')

let win = totimespan({Window});
let src = SecurityIncident
| where CreatedTime > ago(2*win)
| summarize arg_max(LastModifiedTime, *) by IncidentNumber
| where Severity in ({SeverityFilter})
| extend Bucket = iff(CreatedTime > ago(win), 'Cur', 'Prior');
let curRow = src | where Bucket == 'Cur'   | summarize Total=count(), High=countif(Severity=='High'), Closed=countif(Status=='Closed'), NewState=countif(Status=='New'), MTTR=toint(round(avgif(todouble(datetime_diff('hour',ClosedTime,CreatedTime)), Status=='Closed'),0));
let prRow  = src | where Bucket == 'Prior' | summarize Total=count(), High=countif(Severity=='High'), Closed=countif(Status=='Closed'), NewState=countif(Status=='New'), MTTR=toint(round(avgif(todouble(datetime_diff('hour',ClosedTime,CreatedTime)), Status=='Closed'),0));
let pT=toscalar(prRow|project Total); let pH=toscalar(prRow|project High); let pC=toscalar(prRow|project Closed); let pN=toscalar(prRow|project NewState); let pM=toscalar(prRow|project MTTR);
let fmtDelta = (cur:long, pr:long) { iff(coalesce(pr,0)==0, strcat('vs ', tostring(coalesce(pr,0))), strcat(iff(cur>=pr,'▲ +','▼ '), tostring(toint(round((todouble(cur)-todouble(pr))/todouble(pr)*100.0,1))), '%  vs ', tostring(coalesce(pr,0)))) };
union
  (curRow | extend Order=1, Metric='Total Incidents', Value=tolong(Total),    Delta=fmtDelta(tolong(Total),    tolong(coalesce(pT,0)))),
  (curRow | extend Order=2, Metric='High Severity',   Value=tolong(High),     Delta=fmtDelta(tolong(High),     tolong(coalesce(pH,0)))),
  (curRow | extend Order=3, Metric='Closed',          Value=tolong(Closed),   Delta=fmtDelta(tolong(Closed),   tolong(coalesce(pC,0)))),
  (curRow | extend Order=4, Metric='Still NEW',       Value=tolong(NewState), Delta=fmtDelta(tolong(NewState), tolong(coalesce(pN,0)))),
  (curRow | extend Order=5, Metric='Avg MTTR (h)',    Value=tolong(MTTR),     Delta=fmtDelta(tolong(MTTR),     tolong(coalesce(pM,0))))
| project Order, Metric, Value=coalesce(Value, tolong(0)), Delta
| order by Order asc

let win = totimespan({Window});
let inc = SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | where Severity in ({SeverityFilter});
let totalInc = tolong(coalesce(toscalar(inc | count), 0));
let tpInc    = tolong(coalesce(toscalar(inc | where Classification == 'TruePositive' | count), 0));
let classifiedInc = tolong(coalesce(toscalar(inc | where isnotempty(Classification) | count), 0));
let tpRate   = todouble(tpInc) / todouble(iff(classifiedInc==tolong(0), tolong(1), classifiedInc)) * 100.0;
let oldestOpen = toscalar(inc | where Status != 'Closed' | summarize min(CreatedTime));
let backlogDays = tolong(iff(isnull(oldestOpen), tolong(0), tolong(toint(round(todouble(datetime_diff('hour', now(), oldestOpen)) / -24.0, 0)))));
let signins = SigninLogs | where TimeGenerated > ago(win) | summarize Total=count(), Failed=countif(ResultType != 0);
let signTotal  = tolong(coalesce(toscalar(signins | project Total), 0));
let signFailed = tolong(coalesce(toscalar(signins | project Failed), 0));
let failRate   = todouble(signFailed) / todouble(iff(signTotal==tolong(0), tolong(1), signTotal)) * 100.0;
let riskyUsers = tolong(coalesce(toscalar(AADUserRiskEvents | where TimeGenerated > ago(win) | where RiskState in ('atRisk','confirmedCompromised') | summarize dcount(UserPrincipalName)), 0));
let rh = SentinelHealth | where TimeGenerated > ago(7d) | where SentinelResourceType == 'Analytics Rule' | summarize arg_max(TimeGenerated, *) by SentinelResourceId;
let rTotal   = tolong(coalesce(toscalar(rh | count), 0));
let rHealthy = tolong(coalesce(toscalar(rh | where Status == 'Success' | count), 0));
let detCovPct = todouble(rHealthy) / todouble(iff(rTotal==tolong(0), tolong(1), rTotal)) * 100.0;
union
  (print Order=1, Metric='Risky Users',         Value=riskyUsers,                  Sub='atRisk + compromised'),
  (print Order=2, Metric='Sign-In Failure %',   Value=tolong(toint(round(failRate,0))), Sub=strcat(tostring(signFailed), ' / ', tostring(signTotal))),
  (print Order=3, Metric='Detection Coverage',  Value=tolong(toint(round(detCovPct,0))),Sub=strcat(tostring(rHealthy), ' / ', tostring(rTotal), ' rules healthy')),
  (print Order=4, Metric='Backlog (days)',      Value=backlogDays,                 Sub='oldest open incident'),
  (print Order=5, Metric='True-Positive Rate',  Value=tolong(toint(round(tpRate,0))),Sub=strcat(tostring(tpInc), ' TP / ', tostring(classifiedInc), ' classified'))
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let inc = SecurityIncident | where CreatedTime > ago(2*win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | where Severity in ({SeverityFilter}) | project IncidentNumber, CreatedTime, Title, Severity, AlertIds, Bucket = iff(CreatedTime > ago(win), 'Cur', 'Prior') | mv-expand AlertId = AlertIds to typeof(string);
let alerts = SecurityAlert | where TimeGenerated > ago(2*win) | summarize arg_max(TimeGenerated, *) by SystemAlertId | project SystemAlertId, Tactics;
let enriched = inc | join kind=leftouter alerts on $left.AlertId == $right.SystemAlertId | summarize Tactics = make_set(Tactics), Title = any(Title), Bucket = any(Bucket), CreatedTime = any(CreatedTime) by IncidentNumber | extend TS = tolower(tostring(Tactics)), TL = tolower(tostring(Title)) | extend Scenario = case(TS has 'credentialaccess' or TL has_any ('aitm','token theft','oauth','consent grant','password spray','brute force'), '🔓 Account takeover activity', TS has 'initialaccess' and TL has_any ('phish','phishing','email','bec'), '🎣 Phishing-driven compromise', TS has 'lateralmovement' or TL has_any ('lateral','rdp ','psexec','smb '), '🔁 Suspicious lateral movement', TS has 'exfiltration' or TL has_any ('exfil','data leak','mass download','upload to'), '📤 Data exfiltration', TS has 'privilegeescalation' or TL has_any ('privilege escalation','role assigned','global admin'), '⬆️ Privilege escalation', TS has_any ('impact','ransomware') or TL has_any ('ransomware','encrypt','wiper'), '💥 Ransomware / business impact', TS has 'persistence' or TL has_any ('scheduled task','startup','registry run','forwarding rule'), '🪰 Persistence established', 'Other');
let cur = enriched | where Bucket == 'Cur' | summarize Cur = count() by Scenario;
let pr  = enriched | where Bucket == 'Prior' | summarize Prior = count() by Scenario;
cur
| join kind=fullouter pr on Scenario
| extend Scenario = coalesce(Scenario, Scenario1)
| where Scenario != 'Other'
| extend Cur = coalesce(Cur, 0), Prior = coalesce(Prior, 0)
| extend DeltaPct = iff(Prior == 0 and Cur > 0, 999.0, iff(Prior == 0, 0.0, round(100.0*(todouble(Cur)-todouble(Prior))/todouble(Prior), 0)))
| extend TrendIcon = case(DeltaPct >= 50.0, '▲ ▲', DeltaPct >= 10.0, '▲', DeltaPct <= -50.0, '▼ ▼', DeltaPct <= -10.0, '▼', '~')
| extend Trend = iff(DeltaPct == 999.0, strcat(TrendIcon, ' new'), strcat(TrendIcon, ' ', tostring(toint(DeltaPct)), '%'))
| project ['Risk Scenario']=Scenario, ['Incidents']=Cur, ['Prior']=Prior, ['Trend vs prior']=Trend
| order by ['Incidents'] desc
| take 7

let win = totimespan({Window});
let alertCount = tolong(coalesce(toscalar(SecurityAlert | where TimeGenerated > ago(win) | summarize dcount(SystemAlertId)), 0));
let incAlertCount = tolong(coalesce(toscalar(SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | mv-expand AlertId = AlertIds to typeof(string) | summarize dcount(AlertId)), 0));
let incCount = tolong(coalesce(toscalar(SecurityIncident | where CreatedTime > ago(win) | summarize dcount(IncidentNumber)), 0));
let conv = todouble(incAlertCount) / todouble(iff(alertCount == 0, 1, alertCount)) * 100.0;
let apc  = todouble(alertCount) / todouble(iff(incCount == 0, 1, incCount));
union
  (print Order=1, Metric='📡 Total alerts received',  Value=alertCount,                                       Sub='unique SystemAlertId in window'),
  (print Order=2, Metric='🎯 Alerts → incidents',         Value=tolong(toint(round(conv, 0))),                    Sub=strcat(tostring(incAlertCount), ' alerts grouped into ', tostring(incCount), ' incidents')),
  (print Order=3, Metric='📦 Avg alerts per incident', Value=tolong(toint(round(apc, 0))),                     Sub='lower = cleaner detections')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let stageRank = datatable(Tactic:string, Stage:string, Rank:int) [
  'Reconnaissance','🟢 Early stage', 1, 'ResourceDevelopment','🟢 Early stage', 2, 'InitialAccess','🟢 Early stage', 3,
  'Execution','🟡 Mid stage', 4, 'Persistence','🟡 Mid stage', 5, 'PrivilegeEscalation','🟡 Mid stage', 6,
  'DefenseEvasion','🟡 Mid stage', 7, 'CredentialAccess','🟡 Mid stage', 8, 'Discovery','🟡 Mid stage', 9,
  'LateralMovement','🔴 Late stage', 10, 'Collection','🔴 Late stage', 11, 'CommandAndControl','🔴 Late stage', 12,
  'Exfiltration','🔴 Late stage', 13, 'Impact','🔴 Late stage', 14
];
let inc = SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | where Severity in ({SeverityFilter}) | mv-expand AlertId = AlertIds to typeof(string);
let alerts = SecurityAlert | where TimeGenerated between (ago(win + 1d) .. now()) | summarize arg_max(TimeGenerated, *) by SystemAlertId | extend TacticList = extract_all(@'(\w+)', tostring(Tactics)) | mv-expand Tactic = TacticList to typeof(string) | project SystemAlertId, Tactic;
let perInc = inc | join kind=leftouter alerts on $left.AlertId == $right.SystemAlertId | join kind=leftouter stageRank on Tactic | summarize EarliestRank = min(Rank) by IncidentNumber | where isnotnull(EarliestRank);
let total = tolong(coalesce(toscalar(perInc | summarize count()), 0));
perInc
| join kind=leftouter stageRank on $left.EarliestRank == $right.Rank
| summarize Incidents = count() by Stage
| extend Pct = toint(round(100.0 * todouble(Incidents) / todouble(iff(total == 0, 1, total)), 0))
| extend Order = case(Stage startswith '🟢', 1, Stage startswith '🟡', 2, 3)
| extend Sub = strcat(tostring(Incidents), ' of ', tostring(total), ' incidents')
| project Order, Metric=Stage, Value=tolong(Pct), Sub
| order by Order asc

let win = totimespan({Window});
let inc = SecurityIncident | where CreatedTime > ago(2*win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | where Severity in ({SeverityFilter}) | extend Bucket = iff(CreatedTime > ago(win), 'Cur', 'Prior');
let curHigh   = tolong(coalesce(toscalar(inc | where Bucket == 'Cur' and Severity == 'High' | count), 0));
let prHigh    = tolong(coalesce(toscalar(inc | where Bucket == 'Prior' and Severity == 'High' | count), 0));
let oldOpen   = toscalar(inc | where Bucket == 'Cur' and Status != 'Closed' | summarize min(CreatedTime));
let backlog   = tolong(iff(isnull(oldOpen), tolong(0), tolong(toint(round(todouble(datetime_diff('hour', now(), oldOpen)) / -24.0, 0)))));
let risky     = tolong(coalesce(toscalar(AADUserRiskEvents | where TimeGenerated > ago(win) | where RiskState in ('atRisk','confirmedCompromised') | summarize dcount(UserPrincipalName)), 0));
let rh        = SentinelHealth | where TimeGenerated > ago(7d) | where SentinelResourceType == 'Analytics Rule' | summarize arg_max(TimeGenerated, *) by SentinelResourceId;
let rTotal    = tolong(coalesce(toscalar(rh | count), 0));
let rHealthy  = tolong(coalesce(toscalar(rh | where Status == 'Success' | count), 0));
let covPct    = toint(round(todouble(rHealthy) / todouble(iff(rTotal == 0, 1, rTotal)) * 100.0, 0));
let highDelta = toint(round(100.0 * (todouble(curHigh) - todouble(prHigh)) / todouble(iff(prHigh == 0, 1, prHigh)), 0));
let highSpike    = curHigh > prHigh and prHigh > 0 and highDelta >= 25;
let backlogIssue = backlog >= 7;
let riskyIssue   = risky > 0;
let covIssue     = covPct < 90 and rTotal > 0;
let anyIssue     = highSpike or backlogIssue or riskyIssue or covIssue;
union
  (print Order=1, Sev='🔴', Item='High-severity incident spike',
     Detail=strcat('High-sev incidents up ', tostring(highDelta), '% (', tostring(curHigh), ' vs ', tostring(prHigh), ' prior period)'),
     Show=highSpike),
  (print Order=2, Sev='🟠', Item='Backlog age',
     Detail=strcat('Oldest open incident is ', tostring(backlog), ' days old — review SLA'),
     Show=backlogIssue),
  (print Order=3, Sev='🔴', Item='Risky users at risk',
     Detail=strcat(tostring(risky), ' users currently atRisk or confirmed compromised'),
     Show=riskyIssue),
  (print Order=4, Sev='🟠', Item='Detection coverage drop',
     Detail=strcat('Detection coverage at ', tostring(covPct), '%, below 90% target (', tostring(rHealthy), '/', tostring(rTotal), ' rules healthy)'),
     Show=covIssue),
  (print Order=5, Sev='🟢', Item='No attention items',
     Detail='No critical changes detected. Posture is stable across the selected window.',
     Show=not(anyIssue))
| where Show == true
| project Order, Severity=Sev, ['Attention required']=Item, Detail
| order by Order asc

let win = totimespan({Window});
let alerts = AlertInfo | where Timestamp > ago(win);
let total    = tolong(coalesce(toscalar(alerts | count), 0));
let high     = tolong(coalesce(toscalar(alerts | where Severity == 'High' | count), 0));
let mde      = tolong(coalesce(toscalar(alerts | where ServiceSource has 'Microsoft Defender for Endpoint' | count), 0));
let mdi      = tolong(coalesce(toscalar(alerts | where ServiceSource has 'Microsoft Defender for Identity' | count), 0));
let mdo      = tolong(coalesce(toscalar(alerts | where ServiceSource has 'Microsoft Defender for Office' | count), 0));
let mdca     = tolong(coalesce(toscalar(alerts | where ServiceSource has 'Microsoft Defender for Cloud Apps' | count), 0));
union
  (print Order=1, Metric='Total XDR alerts',           Value=total, Sub='all ServiceSources'),
  (print Order=2, Metric='High severity',              Value=high,  Sub='requires attention'),
  (print Order=3, Metric='Defender for Endpoint',      Value=mde,   Sub='device alerts'),
  (print Order=4, Metric='Defender for Identity',      Value=mdi,   Sub='AD/Entra alerts'),
  (print Order=5, Metric='Defender for Office',        Value=mdo,   Sub='email/collab alerts'),
  (print Order=6, Metric='Defender for Cloud Apps',    Value=mdca,  Sub='SaaS alerts')
| project Order, Metric, Value, Sub
| order by Order asc

let win = {Window};
let cur = SecurityAlert | where TimeGenerated > ago(win) | summarize Current = dcount(SystemAlertId) by AlertName;
let prior = SecurityAlert | where TimeGenerated between (ago(2*win) .. ago(win)) | summarize Prior = dcount(SystemAlertId) by AlertName;
cur | join kind=fullouter prior on AlertName
| project AlertName = coalesce(AlertName, AlertName1), Current = coalesce(Current, 0), Prior = coalesce(Prior, 0)
| extend Delta = Current - Prior, DeltaPct = iff(Prior == 0, real(null), round(100.0 * (Current - Prior) / Prior, 1))
| where Current > 10 or Prior > 10
| order by abs(Delta) desc
| take 10

let win = totimespan({Window});
let sevWeight = (s:string) { case(s == 'High', 10.0, s == 'Medium', 5.0, s == 'Low', 2.0, 1.0) };
let score = (start:datetime, end:datetime) {
  let inc = SecurityIncident | where CreatedTime between (start .. end) | summarize arg_max(LastModifiedTime, *) by IncidentNumber;
  let likelihood = toscalar(inc | summarize toreal(count()));
  let impact     = toscalar(inc | summarize sum(sevWeight(Severity)));
  let alerts     = SecurityAlert | where TimeGenerated between (start .. end);
  let exposure   = toscalar(alerts | extend E = extract_all(@'"(?:HostName|AccountName|Address|UserPrincipalName)":"([^"]+)"', tostring(Entities)) | mv-expand E to typeof(string) | summarize toreal(dcount(E)));
  let raw = log10(1.0 + likelihood) * log10(1.0 + impact) * log10(1.0 + exposure);
  toint(round(min_of(100.0, raw * 8.0), 0))
};
let cur   = score(ago(win), now());
let prior = score(ago(2*win), ago(win));
let delta = cur - prior;
let arrow = case(delta >= 5, '↑', delta <= -5, '↓', '→');
let color = case(delta >= 5, '🔴', delta <= -5, '🟢', '🟡');
union
  (print Order=1, Metric='Composite Risk Score', Value=tolong(cur), Sub=strcat(color, ' ', arrow, ' ', tostring(delta), ' vs prior ', tostring(prior))),
  (print Order=2, Metric='Likelihood (incidents)', Value=tolong(toscalar(SecurityIncident | where CreatedTime > ago(win) | summarize dcount(IncidentNumber))), Sub='current window'),
  (print Order=3, Metric='Impact (sev-weighted)',  Value=tolong(toscalar(SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | summarize toint(sum(sevWeight(Severity))))), Sub='10×High + 5×Med + 2×Low'),
  (print Order=4, Metric='Exposure (entities)',    Value=tolong(toscalar(SecurityAlert | where TimeGenerated > ago(win) | extend E = extract_all(@'"(?:HostName|AccountName|Address|UserPrincipalName)":"([^"]+)"', tostring(Entities)) | mv-expand E to typeof(string) | summarize dcount(E))), Sub='distinct hosts/users/IPs')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let curNames   = SecurityAlert | where TimeGenerated > ago(win) | where AlertSeverity in ({SeverityFilter}) | summarize by AlertName;
let priorNames = SecurityAlert | where TimeGenerated between (ago(2*win) .. ago(win)) | where AlertSeverity in ({SeverityFilter}) | summarize by AlertName;
let curCount   = toscalar(curNames | count);
let recurring  = toscalar(curNames | join kind=inner priorNames on AlertName | count);
let netNew     = curCount - recurring;
let retired    = toscalar(priorNames | join kind=leftanti curNames on AlertName | count);
let recurPct   = iff(curCount == 0, 0, toint(round(100.0 * recurring / curCount, 0)));
union
  (print Order=1, Metric='Recurring Risks',   Value=tolong(recurring), Sub=strcat(tostring(recurPct), '% of current detections')),
  (print Order=2, Metric='Net-New Risks',     Value=tolong(netNew),    Sub='first seen this window'),
  (print Order=3, Metric='Retired Risks',     Value=tolong(retired),   Sub='fired prior, silent now'),
  (print Order=4, Metric='Recurrence Rate %', Value=tolong(recurPct),  Sub='control failure indicator')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let curNames   = SecurityAlert | where TimeGenerated > ago(win) | where AlertSeverity in ({SeverityFilter}) | summarize Current = count() by AlertName;
let priorNames = SecurityAlert | where TimeGenerated between (ago(2*win) .. ago(win)) | where AlertSeverity in ({SeverityFilter}) | summarize Prior = count() by AlertName;
curNames
| join kind=leftouter priorNames on AlertName
| project AlertName, Current, Prior = coalesce(Prior, 0)
| extend Status = iff(Prior == 0, '🆕 Net-new', '🔁 Recurring')
| order by Status asc, Current desc
| take 25

let win = totimespan({Window});
let privRoles = dynamic(['Global Administrator','Privileged Role Administrator','Security Administrator','Application Administrator','Cloud Application Administrator','Exchange Administrator','SharePoint Administrator','User Administrator','Conditional Access Administrator','Authentication Administrator','Helpdesk Administrator','Hybrid Identity Administrator','Intune Administrator']);
let alertEntities = SecurityAlert | where TimeGenerated > ago(win) | extend E = extract_all(@'"(?:UserPrincipalName|AccountUpn|HostName|DnsDomain)":"([^"]+)"', tostring(Entities)) | mv-expand E to typeof(string) | summarize by E = tolower(E);
let idAll = IdentityInfo | summarize arg_max(TimeGenerated, *) by AccountUPN | extend Roles = tostring(AssignedRoles);
let privIds = idAll | mv-expand Role = AssignedRoles to typeof(string) | where Role in (privRoles) | summarize by AccountUPN;
let privTotal = toscalar(privIds | count);
let privAtRisk = toscalar(privIds | where tolower(AccountUPN) in (alertEntities) | count);
let privPct = iff(privTotal == 0, 0, toint(round(100.0 * privAtRisk / privTotal, 0)));
let devCriticalTotal = toscalar(DeviceInfo | summarize arg_max(Timestamp, *) by DeviceId | where DeviceCategory == 'Endpoint' or isnotempty(DeviceCategory) | summarize count());
let devCriticalAtRisk = toscalar(DeviceInfo | summarize arg_max(Timestamp, *) by DeviceId | where tolower(DeviceName) in (alertEntities) | summarize count());
let devPct = iff(devCriticalTotal == 0, 0, toint(round(100.0 * devCriticalAtRisk / devCriticalTotal, 0)));
union
  (print Order=1, Metric='Privileged Identities (Total)', Value=tolong(coalesce(privTotal,0)),    Sub='Tier-0 admin roles'),
  (print Order=2, Metric='Privileged At Risk',            Value=tolong(coalesce(privAtRisk,0)),   Sub=strcat(tostring(privPct), '% exposed in window')),
  (print Order=3, Metric='Devices (Total)',               Value=tolong(coalesce(devCriticalTotal,0)), Sub='inventoried in DeviceInfo'),
  (print Order=4, Metric='Devices At Risk',               Value=tolong(coalesce(devCriticalAtRisk,0)),Sub=strcat(tostring(devPct), '% exposed in window'))
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let privRoles = dynamic(['Global Administrator','Privileged Role Administrator','Security Administrator','Application Administrator','Cloud Application Administrator','Exchange Administrator','SharePoint Administrator','User Administrator','Conditional Access Administrator','Authentication Administrator','Helpdesk Administrator','Hybrid Identity Administrator','Intune Administrator']);
let privUsers = IdentityInfo | summarize arg_max(TimeGenerated, *) by AccountUPN | mv-expand Role = AssignedRoles to typeof(string) | where Role in (privRoles) | summarize by AccountUPN = tolower(AccountUPN);
let riskyUsers = SigninLogs | where TimeGenerated > ago(win) | where RiskLevelDuringSignIn in ('high','medium') or RiskState in ('atRisk','confirmedCompromised') | summarize by UPN = tolower(UserPrincipalName);
let riskyTotal = toscalar(riskyUsers | count);
let riskyPriv  = toscalar(riskyUsers | join kind=inner privUsers on $left.UPN == $right.AccountUPN | count);
let pct        = iff(riskyTotal == 0, 0, toint(round(100.0 * riskyPriv / riskyTotal, 0)));
union
  (print Order=1, Metric='High-Risk Users',           Value=tolong(coalesce(riskyTotal,0)), Sub='atRisk + medium/high risk sign-ins'),
  (print Order=2, Metric='Of which Privileged',       Value=tolong(coalesce(riskyPriv,0)),  Sub='hold Tier-0 admin roles'),
  (print Order=3, Metric='% Risk in Privileged',      Value=tolong(coalesce(pct,0)),        Sub='> 10% = fragility signal'),
  (print Order=4, Metric='Privileged Users (Total)',  Value=tolong(toscalar(IdentityInfo | summarize arg_max(TimeGenerated, *) by AccountUPN | mv-expand Role = AssignedRoles to typeof(string) | where Role in (privRoles) | summarize dcount(AccountUPN))), Sub='denominator')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let inc = SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | where Severity in ({SeverityFilter});
let total      = toscalar(inc | count);
let classified = toscalar(inc | where isnotempty(Classification) | count);
let tp         = toscalar(inc | where Classification == 'TruePositive' | count);
let bp         = toscalar(inc | where Classification == 'BenignPositive' | count);
let fp         = toscalar(inc | where Classification == 'FalsePositive' | count);
let tpRate     = iff(classified == 0, 0, toint(round(100.0 * tp / classified, 0)));
let fpRate     = iff(classified == 0, 0, toint(round(100.0 * fp / classified, 0)));
let classRate  = iff(total == 0, 0, toint(round(100.0 * classified / total, 0)));
union
  (print Order=1, Metric='True-Positive Rate %', Value=tolong(tpRate),    Sub=strcat(tostring(tp), ' / ', tostring(classified), ' classified')),
  (print Order=2, Metric='False-Positive Rate %', Value=tolong(fpRate),    Sub=strcat(tostring(fp), ' wasted analyst-hours')),
  (print Order=3, Metric='Benign Positives',     Value=tolong(coalesce(bp,0)), Sub='real activity, not malicious'),
  (print Order=4, Metric='Classification Coverage %', Value=tolong(classRate), Sub=strcat(tostring(classified), ' / ', tostring(total), ' incidents'))
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let entities = SecurityAlert
| where TimeGenerated > ago(win)
| where AlertSeverity in ({SeverityFilter})
| extend E = extract_all(@'"(?:UserPrincipalName|AccountUpn|HostName|Address)":"([^"]+)"', tostring(Entities))
| mv-expand E to typeof(string)
| where isnotempty(E)
| summarize Alerts = count() by Entity = tolower(E);
let total = toscalar(entities | summarize sum(Alerts));
let top5  = toscalar(entities | top 5 by Alerts desc | summarize sum(Alerts));
let top10 = toscalar(entities | top 10 by Alerts desc | summarize sum(Alerts));
let uniq  = toscalar(entities | count);
let idx5  = iff(total == 0, 0, toint(round(100.0 * top5 / total, 0)));
let idx10 = iff(total == 0, 0, toint(round(100.0 * top10 / total, 0)));
union
  (print Order=1, Metric='Concentration Index (Top 5)',  Value=tolong(idx5),  Sub=strcat(tostring(top5),  ' / ', tostring(total), ' alerts')),
  (print Order=2, Metric='Concentration Index (Top 10)', Value=tolong(idx10), Sub='> 60% = highly concentrated'),
  (print Order=3, Metric='Distinct Risky Entities',      Value=tolong(coalesce(uniq,0)), Sub='users + hosts + IPs in alerts'),
  (print Order=4, Metric='Total Alert Entity Hits',      Value=tolong(coalesce(total,0)), Sub='denominator')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let bucket = case(win <= 1d, 1h, win <= 7d, 6h, win <= 30d, 1d, 7d);
let alerts = SecurityAlert | where TimeGenerated > ago(win) | where AlertSeverity in ({SeverityFilter}) | summarize Alerts = count() by bin(TimeGenerated, bucket);
let inc    = SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | where Severity in ({SeverityFilter}) | summarize Incidents = count() by bin(CreatedTime, bucket);
alerts
| join kind=fullouter inc on $left.TimeGenerated == $right.CreatedTime
| project Time = coalesce(TimeGenerated, CreatedTime), Alerts = coalesce(Alerts, 0), Incidents = coalesce(Incidents, 0)
| extend ['Alerts/Incident'] = iff(Incidents == 0, real(null), round(todouble(Alerts) / Incidents, 1))
| order by Time asc

let win = totimespan({Window});
let history = SecurityIncident | where CreatedTime > ago(win) | where Severity in ({SeverityFilter});
let wasClosed = history | summarize WasClosed = countif(Status == 'Closed') by IncidentNumber;
let current   = history | summarize arg_max(LastModifiedTime, *) by IncidentNumber | project IncidentNumber, CurrentStatus = Status;
wasClosed
| join kind=inner current on IncidentNumber
| extend Reopened = WasClosed > 0 and CurrentStatus != 'Closed'
| summarize Total = count(), ReopenedCount = countif(Reopened)
| extend ReopenRate = round(100.0 * ReopenedCount / Total, 1)
| project ['Total Incidents'] = Total, Reopened = ReopenedCount, ['Reopen Rate %'] = ReopenRate

let win = totimespan({Window});
let history = SecurityIncident | where CreatedTime > ago(win) | where Severity in ({SeverityFilter});
let wasClosed = history | summarize WasClosed = countif(Status == 'Closed'), FirstClosed = minif(LastModifiedTime, Status == 'Closed') by IncidentNumber;
let current   = history | summarize arg_max(LastModifiedTime, *) by IncidentNumber;
wasClosed
| join kind=inner current on IncidentNumber
| where WasClosed > 0 and Status != 'Closed'
| extend ReopenLagHours = round(datetime_diff('minute', LastModifiedTime, FirstClosed) / 60.0, 1)
| project IncidentNumber, Title, Severity, FirstClosed, ReopenedAt = LastModifiedTime, ReopenLagHours, Owner = tostring(Owner)
| order by ReopenedAt desc
| take 25

let win = totimespan({Window});
let bucket = case(win <= 1d, 1h, win <= 7d, 6h, win <= 30d, 1d, 7d);
let opens  = SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | where Severity in ({SeverityFilter}) | summarize Opened = count() by bin(CreatedTime, bucket);
let closes = SecurityIncident | where ClosedTime > ago(win) | summarize arg_max(LastModifiedTime, *) by IncidentNumber | where Severity in ({SeverityFilter}) and Status == 'Closed' | summarize Closed = count() by bin(ClosedTime, bucket);
opens
| join kind=fullouter closes on $left.CreatedTime == $right.ClosedTime
| project Time = coalesce(CreatedTime, ClosedTime), Opened = coalesce(Opened, 0), Closed = coalesce(Closed, 0)
| extend Net = Opened - Closed
| order by Time asc

let win = totimespan({Window});
let inc = SecurityIncident
| where CreatedTime > ago(win)
| summarize arg_max(LastModifiedTime, *) by IncidentNumber
| where Severity in ({SeverityFilter});
let total       = toscalar(inc | count);
let autoTouched = toscalar(inc | where tostring(Owner) has_any ('automation','playbook','logicapps','SYSTEM') | count);
let autoClosed  = toscalar(inc | where Status == 'Closed' and isempty(tostring(ClassificationComment)) and datetime_diff('minute', ClosedTime, CreatedTime) <= 5 | count);
let anyClosed   = toscalar(inc | where Status == 'Closed' | count);
union
  (print Order=1, Metric='Automation Rate %', Value=tolong(iff(total==0,0,toint(round(100.0*autoTouched/total,0)))), Sub=strcat(tostring(autoTouched), ' / ', tostring(total), ' touched by automation')),
  (print Order=2, Metric='Auto-Closed %',     Value=tolong(iff(anyClosed==0,0,toint(round(100.0*autoClosed/anyClosed,0)))), Sub=strcat(tostring(autoClosed), ' / ', tostring(anyClosed), ' closed without analyst')),
  (print Order=3, Metric='Manual Closures',   Value=tolong(coalesce(anyClosed - autoClosed, 0)), Sub='analyst-classified'),
  (print Order=4, Metric='Open (no automation)', Value=tolong(toscalar(inc | where Status != 'Closed' and not(tostring(Owner) has_any ('automation','playbook','logicapps','SYSTEM')) | count)), Sub='need analyst attention')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let priv  = IdentityInfo | summarize arg_max(TimeGenerated, *) by AccountUPN | where array_length(AssignedRoles) > 0 | distinct UPN = tolower(AccountUPN);
let risky = AADUserRiskEvents | where TimeGenerated > ago(win) | distinct UPN = tolower(UserPrincipalName);
let flagged = SigninLogs | where TimeGenerated > ago(win) | where RiskLevelDuringSignIn in ('high','medium','low') | project UPN = tolower(UserPrincipalName), CorrelationId;
let total     = toscalar(flagged | summarize dcount(CorrelationId));
let privCount = toscalar(flagged | where UPN in (priv)  | summarize dcount(CorrelationId));
let riskCount = toscalar(flagged | where UPN in (risky) | summarize dcount(CorrelationId));
let bothCount = toscalar(flagged | where UPN in (priv) and UPN in (risky) | summarize dcount(CorrelationId));
union
  (print Order=1, Metric='Flagged Sessions',           Value=tolong(coalesce(total,0)),      Sub='risky sign-ins (low/med/high)'),
  (print Order=2, Metric='% Tied to Privileged Users', Value=tolong(iff(total==0,0,toint(round(100.0*privCount/total,0)))), Sub=strcat(tostring(privCount),' sessions')),
  (print Order=3, Metric='% Tied to High-Risk Users',  Value=tolong(iff(total==0,0,toint(round(100.0*riskCount/total,0)))), Sub=strcat(tostring(riskCount),' sessions')),
  (print Order=4, Metric='⚠️ Privileged AND High-Risk', Value=tolong(coalesce(bothCount,0)),  Sub='top-priority investigation')
| order by Order asc

let win = totimespan({Window});
let totalIds = toscalar(IdentityInfo | summarize dcount(tolower(AccountUPN)));
let risky    = toscalar(SigninLogs       | where TimeGenerated > ago(win) | where RiskLevelDuringSignIn in ('high','medium','low') | summarize dcount(tolower(UserPrincipalName)));
let attacks  = toscalar(AADUserRiskEvents | where TimeGenerated > ago(win) | summarize dcount(tolower(UserPrincipalName)));
let ueba     = toscalar(BehaviorAnalytics | where TimeGenerated > ago(win) | where InvestigationPriority >= 5 | summarize dcount(tolower(UserPrincipalName)));
