union
  (print Order=1, Metric='Identity Risk Posture %', Value=tolong(iff(totalIds==0,0,toint(round(100.0*atRisk/totalIds,0)))), Sub=strcat(tostring(atRisk),' of ',tostring(totalIds),' identities at risk')),
  (print Order=2, Metric='Risky Sign-Ins',                Value=tolong(coalesce(risky,0)),   Sub='unique users'),
  (print Order=3, Metric='UEBA Anomalies (priority ≥ 5)', Value=tolong(coalesce(ueba,0)),    Sub='unique users'),
