let win = totimespan({Window});
let risky = SigninLogs | where TimeGenerated > ago(win) | where RiskLevelDuringSignIn in ('high','medium','low');
let total      = toscalar(risky | count);
let blocked    = toscalar(risky | where ConditionalAccessStatus == 'failure' or ResultType in (50053,50057,50158,53000,530032,530034) | count);
