    AppL has_any ('cursor','codeium','tabnine','replit','github copilot'), '💻 AI Code',
    AppL has_any ('midjourney','runway','suno','elevenlabs','leonardo','heygen','synthesia','dall-e'), '🎨 AI Image/Audio/Video',
    AppL has_any ('mcp','agent','autogen','crewai','langchain','llamaindex'), '🧩 MCP/Agent',
    AppL has_any ('perplexity','phind','kagi','you.com'), '🔍 AI Search',
    AppL has_any ('chatgpt','openai','gpt','gemini','bard','claude','anthropic','grok','xai','deepseek','mistral','meta.ai','character','poe','llama','cohere','huggingface'), '🤖 LLM / Foundation',
    AppL has 'copilot', '🤖 Copilot (other)',
    '🟠 Other AI')
| summarize Events=count(), Users=dcount(User) by Category
| order by Users desc

let win = totimespan({Window});
let aiKw = dynamic(['Copilot','AI','Agent','GPT','Gemini','Grok','Anthropic','Claude','OpenAI','ChatGPT','Perplexity','HuggingFace','Mistral','DeepSeek','Cohere','Cursor','Codeium','Tabnine','Replit','Midjourney','Runway','Suno','ElevenLabs','Leonardo','Heygen','Synthesia','Phind','Kagi','LangChain','AutoGen','CrewAI','LlamaIndex','Llama','MCP','Bedrock','Vertex','Bard','xAI']);
let endpointKw = dynamic(['chatgpt','openai.com','claude.ai','anthropic','gemini.google','bard.google','perplexity','huggingface','mistral.ai','deepseek','cohere','grok.com','x.ai','meta.ai','character.ai','cursor.sh','codeium','tabnine','replit','midjourney','runwayml','suno.com','elevenlabs','leonardo.ai','heygen','synthesia','phind','kagi','poe.com']);
let hostMap = (t:(RemoteUrl:string)) { t | extend Host=tolower(extract(@'^(?:https?://)?([^/]+)', 1, RemoteUrl)) | extend App = case(Host endswith 'chatgpt.com' or Host endswith 'openai.com','ChatGPT / OpenAI', Host endswith 'claude.ai' or Host endswith 'anthropic.com','Claude (Anthropic)', Host endswith 'gemini.google.com' or Host endswith 'bard.google.com','Gemini (Google)', Host endswith 'perplexity.ai','Perplexity', Host endswith 'huggingface.co','Hugging Face', Host endswith 'mistral.ai','Mistral', Host has 'deepseek','DeepSeek', Host endswith 'cohere.com','Cohere', Host endswith 'grok.com' or Host endswith 'x.ai','Grok (xAI)', Host endswith 'meta.ai','Meta AI', Host endswith 'character.ai','Character.AI', Host endswith 'cursor.sh','Cursor', Host has 'codeium','Codeium', Host has 'tabnine','Tabnine', Host endswith 'replit.com','Replit', Host endswith 'midjourney.com','Midjourney', Host has 'runway','Runway', Host endswith 'suno.com','Suno', Host endswith 'elevenlabs.io','ElevenLabs', Host endswith 'leonardo.ai','Leonardo.AI', Host endswith 'heygen.com','HeyGen', Host endswith 'synthesia.io','Synthesia', Host endswith 'phind.com','Phind', Host endswith 'kagi.com','Kagi', Host endswith 'poe.com','Poe', Host) };
let baselineSaaS = CloudAppEvents | where TimeGenerated between (ago(90d) .. ago(win)) | where Application has_any (aiKw) | summarize by App=Application;
let baselineFed = union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs | where TimeGenerated between (ago(90d) .. ago(win)) | where AppDisplayName has_any (aiKw) | summarize by App=AppDisplayName;
let baselineEndp = DeviceNetworkEvents | where TimeGenerated between (ago(90d) .. ago(win)) | where RemoteUrl has_any (endpointKw) | invoke hostMap() | summarize by App;
let baseline = union baselineSaaS, baselineFed, baselineEndp;
let curSaaS = CloudAppEvents | where TimeGenerated > ago(win) | where Application has_any (aiKw) | extend App=Application, User=tolower(AccountId), Source='🏢 SaaS' | project TimeGenerated, App, User, Source;
let curFed = union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs | where TimeGenerated > ago(win) | where AppDisplayName has_any (aiKw) | extend App=AppDisplayName, User=tolower(UserPrincipalName), Source='🔐 Federated' | project TimeGenerated, App, User, Source;
let curEndp = DeviceNetworkEvents | where TimeGenerated > ago(win) | where RemoteUrl has_any (endpointKw) | invoke hostMap() | extend User=tolower(InitiatingProcessAccountName), Source='💻 Endpoint' | project TimeGenerated, App, User, Source;
union curSaaS, curFed, curEndp
| summarize FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Events=count(), Users=dcount(User), SampleUsers=make_set(User,5) by App, Source
| join kind=leftanti baseline on App
| order by Users desc, Events desc
| take 20

let win = totimespan({Window});
let aiKw = dynamic(['chatgpt','openai','gemini','claude','anthropic','perplexity','copilot','huggingface','deepseek','mistral','grok']);
let riskyUsers = AADUserRiskEvents | where TimeGenerated > ago(win) | where RiskState in ('atRisk','confirmedCompromised') | summarize by tolower(UserPrincipalName);
let aiUsers = CloudAppEvents | where TimeGenerated > ago(win) | where Application has_any (aiKw) | summarize AIEvents = count() by User = tolower(AccountId);
let allAi = toscalar(aiUsers | summarize sum(AIEvents));
let overlap = aiUsers | where User in (riskyUsers) | summarize OverlapEvents = sum(AIEvents), OverlapUsers = dcount(User);
let allUsers = toscalar(aiUsers | summarize dcount(User));
overlap
| extend Order=1, Metric='Risky users using AI', Value=tolong(OverlapUsers), Sub=strcat(tostring(toint(round(100.0 * OverlapUsers / iff(allUsers==0,1,allUsers), 0))), '% of all AI users')
| union (overlap | extend Order=2, Metric='AI events from risky users', Value=tolong(OverlapEvents), Sub=strcat(tostring(toint(round(100.0 * OverlapEvents / iff(allAi==0,1,allAi), 0))), '% of all AI activity'))
| order by Order asc
| project Metric, Value, Sub

let win = totimespan({Window});
let dlp = SecurityAlert | where TimeGenerated > ago(win) | where ProductName has_any ('Data Loss Prevention','Cloud Apps','Insider Risk','Purview') or AlertName has_any ('DLP','Sensitivity','Label','sensitive');
let total = toscalar(dlp | summarize count());
let blocked = toscalar(dlp | where AlertName has_any ('Blocked','Prevented','Quarantined') or ExtendedProperties has 'Blocked' | summarize count());
let allowed = toscalar(dlp | where AlertName has_any ('Allowed','Override','User justified','Bypass') | summarize count());
let audited = total - blocked - allowed;
union (print Order=1, Metric='🟢 Blocked / Prevented', Value=tolong(blocked), Sub=strcat(tostring(toint(round(100.0 * blocked / iff(total==0,1,total),0))), '% of DLP events')),
      (print Order=2, Metric='🟠 Allowed / Override', Value=tolong(allowed), Sub=strcat(tostring(toint(round(100.0 * allowed / iff(total==0,1,total),0))), '% of DLP events')),
      (print Order=3, Metric='🔵 Audited only', Value=tolong(audited), Sub=strcat(tostring(toint(round(100.0 * audited / iff(total==0,1,total),0))), '% — control NOT enforcing'))
| order by Order asc
| project Metric, Value, Sub

let win = totimespan({Window});
let aiKw = dynamic(['Copilot','AI','Agent','GPT','Gemini','Grok','Anthropic','Claude','OpenAI','ChatGPT','Perplexity','HuggingFace','Mistral','DeepSeek','Cohere','Cursor','Codeium','Tabnine','Replit','Midjourney','Runway','Suno','ElevenLabs','Leonardo','Heygen','Synthesia','Phind','Kagi','LangChain','AutoGen','CrewAI','LlamaIndex','Llama','MCP','Bedrock','Vertex','Bard','xAI']);
let endpointKw = dynamic(['chatgpt','openai.com','claude.ai','anthropic','gemini.google','bard.google','perplexity','huggingface','mistral.ai','deepseek','cohere','grok.com','x.ai','meta.ai','character.ai','cursor.sh','codeium','tabnine','replit','midjourney','runwayml','suno.com','elevenlabs','leonardo.ai','heygen','synthesia','phind','kagi','poe.com']);
let histSaaS = CloudAppEvents | where TimeGenerated between (ago(180d) .. ago(win)) | where Application has_any (aiKw) | summarize by User=tolower(AccountId);
let histFed = union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs | where TimeGenerated between (ago(180d) .. ago(win)) | where AppDisplayName has_any (aiKw) | summarize by User=tolower(UserPrincipalName);
