let historic = union histSaaS, histFed, histEndp | summarize by User;
let curSaaS = CloudAppEvents | where TimeGenerated > ago(win) | where Application has_any (aiKw) | extend User=tolower(AccountId), App=Application, Source='🏢 SaaS' | project TimeGenerated, User, App, Source;
let curFed = union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs | where TimeGenerated > ago(win) | where AppDisplayName has_any (aiKw) | extend User=tolower(UserPrincipalName), App=AppDisplayName, Source='🔐 Federated' | project TimeGenerated, User, App, Source;
let curEndp = DeviceNetworkEvents | where TimeGenerated > ago(win) | where RemoteUrl has_any (endpointKw) | extend User=tolower(InitiatingProcessAccountName), Host=tolower(extract(@'^(?:https?://)?([^/]+)', 1, RemoteUrl)) | extend App = case(Host endswith 'chatgpt.com' or Host endswith 'openai.com','ChatGPT/OpenAI', Host endswith 'claude.ai' or Host endswith 'anthropic.com','Claude', Host endswith 'gemini.google.com','Gemini', Host endswith 'perplexity.ai','Perplexity', Host endswith 'huggingface.co','HuggingFace', Host endswith 'grok.com' or Host endswith 'x.ai','Grok', Host endswith 'meta.ai','Meta AI', Host) | extend Source='💻 Endpoint' | project TimeGenerated, User, App, Source;
union curSaaS, curFed, curEndp
| where isnotempty(User) and User !in ('system','-')
| summarize FirstUse=min(TimeGenerated), Events=count(), Apps=make_set(App,5), Sources=make_set(Source) by User
| join kind=leftanti historic on User
| project User, ['First AI Use']=FirstUse, ['AI Events']=Events, Apps, Sources
| order by ['First AI Use'] asc
| take 25

let win = totimespan({Window});
let aiKw = dynamic(['Copilot','AI','Agent','GPT','Gemini','Grok','Anthropic','Claude','OpenAI','ChatGPT','Perplexity','HuggingFace','Mistral','DeepSeek','Cohere','Cursor','Codeium','Tabnine','Replit','Midjourney','Runway','Suno','ElevenLabs','Leonardo','Heygen','Synthesia','Phind','Kagi','LangChain','AutoGen','CrewAI','LlamaIndex','Llama','MCP','Bedrock','Vertex','Bard','xAI']);
let highRisk = dynamic(['CN','RU','KP','IR','BY','VE','SY']);
let standard = dynamic(['US','GB','DE','FR','ES','NL','IE','CA','AU','JP','SE','NO','DK','FI','BE','IT','PT','PL','CH','AT']);
