let siGeo = SigninLogs | where TimeGenerated > ago(win) | where AppDisplayName has_any (aiKw) | extend CC = tostring(parse_json(tostring(LocationDetails)).countryOrRegion) | where isnotempty(CC) | project TimeGenerated, CC;
let niGeo = AADNonInteractiveUserSignInLogs | where TimeGenerated > ago(win) | where AppDisplayName has_any (aiKw) | extend CC = tostring(parse_json(tostring(LocationDetails)).countryOrRegion) | where isnotempty(CC) | project TimeGenerated, CC;
