let topApps = ai | summarize V=count() by App | top 5 by V desc | summarize V=sum(V);
let topIPs = ai | where isnotempty(IP) | summarize V=count() by IP | top 10 by V desc | summarize V=sum(V);
union (print Order=1, Metric='Top 10 users', Value=tolong(toscalar(topUsers)), Sub=strcat(tostring(toint(round(100.0 * toscalar(topUsers) / iff(total==0,1,total), 0))), '% of all AI activity')),
      (print Order=2, Metric='Top 5 AI apps', Value=tolong(toscalar(topApps)), Sub=strcat(tostring(toint(round(100.0 * toscalar(topApps) / iff(total==0,1,total), 0))), '% of all AI activity')),
      (print Order=3, Metric='Top 10 IPs', Value=tolong(toscalar(topIPs)), Sub=strcat(tostring(toint(round(100.0 * toscalar(topIPs) / iff(total==0,1,total), 0))), '% of all AI activity'))
| order by Order asc
| project Metric, Value, Sub

let win = totimespan({Window});
let alerts = toscalar(SecurityAlert | where TimeGenerated > ago(win) | summarize dcount(SystemAlertId));
let incidents = toscalar(SecurityIncident | where CreatedTime > ago(win) | summarize dcount(IncidentNumber));
let incLatest = SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(TimeGenerated,*) by IncidentNumber;
let multi = toscalar(incLatest | where array_length(AlertIds) > 1 | summarize dcount(IncidentNumber));
let tps = toscalar(incLatest | where Classification == 'TruePositive' | summarize dcount(IncidentNumber));
let mitreMapped = toscalar(SecurityAlert | where TimeGenerated > ago(win) | where isnotempty(Tactics) | summarize dcount(SystemAlertId));
union (print Order=1, Metric='Alerts fired', Value=tolong(alerts), Sub='raw detections'),
      (print Order=2, Metric='Incidents created', Value=tolong(incidents), Sub=strcat(tostring(toint(round(100.0 * incidents / iff(alerts==0,1,alerts), 0))), '% of alerts')),
      (print Order=3, Metric='Multi-alert incidents', Value=tolong(multi), Sub='higher-confidence detections'),
      (print Order=4, Metric='True positives', Value=tolong(tps), Sub=strcat(tostring(toint(round(100.0 * tps / iff(incidents==0,1,incidents), 0))), '% of incidents')),
      (print Order=5, Metric='MITRE-mapped alerts', Value=tolong(mitreMapped), Sub=strcat(tostring(toint(round(100.0 * mitreMapped / iff(alerts==0,1,alerts), 0))), '% of alerts'))
| order by Order asc
| project Metric, Value, Sub

let win = totimespan({Window});
let sa = SecurityAlert | where TimeGenerated > ago(win) | where isnotempty(EndTime) | extend LatencyMin = datetime_diff('minute', TimeGenerated, EndTime) | where LatencyMin between (0 .. (60*24*7));
let med = toscalar(sa | summarize percentile(LatencyMin, 50));
let p95 = toscalar(sa | summarize percentile(LatencyMin, 95));
let maxv = toscalar(sa | summarize max(LatencyMin));
union (print Order=1, Metric='⏱️ Median latency', Value=tolong(med), Sub='minutes from event → alert'),
      (print Order=2, Metric='⏱️ P95 latency', Value=tolong(p95), Sub='95th percentile (minutes)'),
