| order by Order asc
| project Metric, Value, Sub

let win = totimespan({Window});
let healthy = SentinelHealth | where TimeGenerated > ago(win) | where SentinelResourceType == 'Analytics Rule' | summarize arg_max(TimeGenerated, *) by SentinelResourceId | where Status == 'Success' | project RuleName = SentinelResourceName, Last = TimeGenerated;
let fired = SecurityAlert | where TimeGenerated > ago(win) | summarize Alerts = count() by RuleName = AlertName;
healthy
| join kind=leftouter fired on RuleName
| where isempty(Alerts) or Alerts == 0
| project RuleName, ['Last health check'] = Last, ['Alerts in window'] = 0
| order by ['Last health check'] desc
| take 30

let win = totimespan({Window});
let gb = toscalar(Usage | where TimeGenerated > ago(win) | where IsBillable == true | summarize sum(Quantity) / 1024.0);
let inc = toscalar(SecurityIncident | where CreatedTime > ago(win) | summarize dcount(IncidentNumber));
let tps = toscalar(SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(TimeGenerated, *) by IncidentNumber | where Classification == 'TruePositive' | summarize dcount(IncidentNumber));
let assets = toscalar(Heartbeat | where TimeGenerated > ago(win) | summarize dcount(Computer));
union (print Order=1, Metric='💾 Total GB ingested', Value=tolong(round(gb, 0)), Sub='billable in window'),
      (print Order=2, Metric='💰 GB per incident', Value=tolong(round(gb / iff(inc==0,1,inc), 0)), Sub=strcat(tostring(inc), ' incidents')),
      (print Order=3, Metric='🎯 GB per true positive', Value=tolong(round(gb / iff(tps==0,1,tps), 0)), Sub=strcat(tostring(tps), ' TPs — high = poor signal/cost')),
      (print Order=4, Metric='🖥️ GB per monitored asset', Value=tolong(round(gb / iff(assets==0,1,assets), 0)), Sub=strcat(tostring(assets), ' Heartbeat assets'))
| order by Order asc
| project Metric, Value, Sub

let win = totimespan({Window});
let allTactics = 14;
let highRisk = dynamic(['CredentialAccess','LateralMovement','Exfiltration','Impact','CommandAndControl']);
let alerts = SecurityAlert | where TimeGenerated > ago(win) | where AlertSeverity in ({SeverityFilter}) | extend T = split(Tactics, ',') | mv-expand T | extend Tactic = trim(' ', tostring(T)) | where isnotempty(Tactic);
let activeTactics = toscalar(alerts | summarize dcount(Tactic));
let hrActive = toscalar(alerts | where Tactic in (highRisk) | summarize dcount(Tactic));
let hrTotal = array_length(highRisk);
let incLatest = SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(TimeGenerated,*) by IncidentNumber;
let totalInc = toscalar(incLatest | summarize dcount(IncidentNumber));
let incTactics = incLatest | mv-expand AlertId = AlertIds to typeof(string) | join kind=inner (alerts | project SystemAlertId, Tactic) on $left.AlertId == $right.SystemAlertId | summarize TacSet = make_set(Tactic) by IncidentNumber;
let multi = toscalar(incTactics | where array_length(TacSet) > 1 | summarize dcount(IncidentNumber));
let avgDepth = toscalar(incTactics | summarize round(avg(toreal(array_length(TacSet))), 1));
let beforeLM = toscalar(incTactics | where not(TacSet has_any ('LateralMovement','Exfiltration','Impact')) | summarize dcount(IncidentNumber));
let beforeLMPct = toint(round(100.0 * beforeLM / iff(totalInc==0,1,totalInc), 0));
union
 (print Order=1, Metric='🎯 Active tactic coverage', Value=tolong(coalesce(activeTactics,0)), Sub=strcat('of ', tostring(allTactics), ' tactics (', tostring(toint(round(100.0 * coalesce(activeTactics,0) / allTactics, 0))), '%) actually triggering')),
 (print Order=2, Metric='🛑 Detected before lateral movement', Value=tolong(beforeLMPct), Sub=strcat(tostring(beforeLM), ' / ', tostring(totalInc), ' incidents — KILLER KPI (% detected pre-LM/Exfil/Impact)')),
 (print Order=3, Metric='🔴 High-risk tactics active', Value=tolong(coalesce(hrActive,0)), Sub=strcat('of ', tostring(hrTotal), ' (CredAccess/LM/C2/Exfil/Impact)')),
 (print Order=4, Metric='🧬 Multi-tactic incidents', Value=tolong(coalesce(multi,0)), Sub=strcat(tostring(toint(round(100.0 * coalesce(multi,0) / iff(totalInc==0,1,totalInc), 0))), '% of incidents — attack progression')),
 (print Order=5, Metric='📊 Detection depth', Value=tolong(toint(round(coalesce(avgDepth,0.0), 0))), Sub='avg distinct tactics per incident')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let alerts = SecurityAlert | where TimeGenerated > ago(win) | where AlertSeverity in ({SeverityFilter}) | extend T = split(Tactics, ',') | mv-expand T | extend Tactic = trim(' ', tostring(T)) | where isnotempty(Tactic);
let alertCounts = alerts | summarize Alerts = dcount(SystemAlertId) by Tactic;
let incLatest = SecurityIncident | where CreatedTime > ago(win) | summarize arg_max(TimeGenerated,*) by IncidentNumber;
let incTac = incLatest | mv-expand AlertId = AlertIds to typeof(string) | join kind=inner (alerts | project SystemAlertId, Tactic) on $left.AlertId == $right.SystemAlertId;
let incCounts = incTac | summarize Incidents = dcount(IncidentNumber), TPs = dcountif(IncidentNumber, Classification == 'TruePositive') by Tactic;
alertCounts
| join kind=leftouter incCounts on Tactic
| extend Incidents = coalesce(Incidents, 0), TPs = coalesce(TPs, 0)
| extend ['TP Rate %'] = toint(round(100.0 * TPs / iff(Alerts==0,1,Alerts), 0))
| extend ['Inc Rate %'] = toint(round(100.0 * Incidents / iff(Alerts==0,1,Alerts), 0))
| project Tactic, Alerts, Incidents, TPs, ['Inc Rate %'], ['TP Rate %']
| order by Alerts desc

let win = totimespan({Window});
let healthy = SentinelHealth | where TimeGenerated > ago(win) | where SentinelResourceType == 'Analytics Rule' | summarize arg_max(TimeGenerated, *) by SentinelResourceId | where Status == 'Success' | project RuleName = SentinelResourceName;
let fired = SecurityAlert | where TimeGenerated > ago(win) | summarize Alerts = count() by RuleName = AlertName;
healthy
| join kind=leftouter fired on RuleName
| where isempty(Alerts) or Alerts == 0
| project ['Unexercised rule'] = RuleName, ['Alerts in window'] = 0
