let win = totimespan({Window});
let mail = EmailEvents | where Timestamp > ago(win) | where EmailDirection == 'Inbound';
let threats = mail | where ThreatTypes has_any ('Phish','Malware');
let phish = threats | where ThreatTypes has 'Phish';
let total = tolong(coalesce(toscalar(threats | count), 0));
let blocked = tolong(coalesce(toscalar(threats | where DeliveryLocation in ('Quarantine','Blocked','Failed','Dropped') or DeliveryAction == 'Blocked' | count), 0));
let delivered = tolong(coalesce(toscalar(threats | where DeliveryLocation in ('Inbox/folder','Junk folder') | count), 0));
let zapped = tolong(coalesce(toscalar(EmailPostDeliveryEvents | where Timestamp > ago(win) | where ActionType has_any ('ZAP','Zap') or ActionType has 'Phish' or ActionType has 'Malware' | summarize dcount(NetworkMessageId)), 0));
let phishDelivered = phish | where DeliveryLocation in ('Inbox/folder','Junk folder');
let phishDeliveredIds = toscalar(phishDelivered | summarize make_set(NetworkMessageId));
let phishDeliveredCount = tolong(coalesce(toscalar(phishDelivered | summarize dcount(NetworkMessageId)), 0));
let phishClicked = tolong(coalesce(toscalar(UrlClickEvents | where Timestamp > ago(win) | where NetworkMessageId in (phishDeliveredIds) | summarize dcount(NetworkMessageId)), 0));
let killer = toint(round(100.0 * phishClicked / iff(phishDeliveredCount==0,1,phishDeliveredCount), 1));
union
 (print Order=1, Metric='🟢 Blocked pre-delivery', Value=tolong(toint(round(100.0*blocked/iff(total==0,1,total),0))), Sub=strcat(tostring(blocked), ' / ', tostring(total), ' threat mails blocked')),
 (print Order=2, Metric='🟠 Delivered to mailbox', Value=tolong(toint(round(100.0*delivered/iff(total==0,1,total),0))), Sub=strcat(tostring(delivered), ' threat mails reached inbox/junk')),
 (print Order=3, Metric='♻️ Remediated by ZAP', Value=tolong(zapped), Sub='post-delivery removals'),
 (print Order=4, Metric='🔴 KILLER — % phishing reached AND clicked', Value=tolong(killer), Sub=strcat(tostring(phishClicked), ' / ', tostring(phishDeliveredCount), ' delivered phish were clicked')),
 (print Order=5, Metric='✉️ Total threat mails', Value=tolong(total), Sub='phish + malware (inbound)')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let mail = EmailEvents | where Timestamp > ago(win) | where EmailDirection == 'Inbound';
let inboxed      = todouble(coalesce(toscalar(mail | where DeliveryLocation in ('Inbox/folder','Junk folder') | count), 0));
let phishInbox   = todouble(coalesce(toscalar(mail | where ThreatTypes has 'Phish'   | where DeliveryLocation in ('Inbox/folder','Junk folder') | count), 0));
let malwareInbox = todouble(coalesce(toscalar(mail | where ThreatTypes has 'Malware' | where DeliveryLocation in ('Inbox/folder','Junk folder') | count), 0));
let denom = iff(inboxed == 0.0, 1.0, inboxed);
union
  (print Metric='% phishing in mailbox', Pct = phishInbox   / denom),
  (print Metric='% malware in mailbox',  Pct = malwareInbox / denom)

let win = totimespan({Window});
let clicks = UrlClickEvents | where Timestamp > ago(win);
let total = tolong(coalesce(toscalar(clicks | summarize count()), 0));
let malicious = tolong(coalesce(toscalar(clicks | where ThreatTypes has_any ('Phish','Malware') | summarize count()), 0));
let through = tolong(coalesce(toscalar(clicks | where IsClickedThrough == true | summarize count()), 0));
let maliciousThrough = tolong(coalesce(toscalar(clicks | where ThreatTypes has_any ('Phish','Malware') and IsClickedThrough == true | summarize count()), 0));
let uniqueClickers = tolong(coalesce(toscalar(clicks | where ThreatTypes has_any ('Phish','Malware') | summarize dcount(AccountUpn)), 0));
union
 (print Order=1, Metric='🖥️ Total Safe Links clicks', Value=tolong(total), Sub='all URL clicks in window'),
 (print Order=2, Metric='⚠️ Clicks on malicious URLs', Value=tolong(malicious), Sub=strcat(tostring(toint(round(100.0*malicious/iff(total==0,1,total),2))), '% of all clicks')),
 (print Order=3, Metric='🔴 Bypassed warning page', Value=tolong(maliciousThrough), Sub=strcat(tostring(toint(round(100.0*maliciousThrough/iff(malicious==0,1,malicious),0))), '% clicked through warning')),
 (print Order=4, Metric='👤 Distinct users clicking phishing', Value=tolong(uniqueClickers), Sub='unique recipients exposed')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let riskySignIn = SigninLogs | where TimeGenerated > ago(win) | where RiskLevelDuringSignIn in ('high','medium','low') or RiskState in ('atRisk','confirmedCompromised') | summarize ['Risky Sign-Ins']=count(), ['Max Risk']=max(RiskLevelDuringSignIn) by UPN = tolower(UserPrincipalName);
let phishClickers = UrlClickEvents | where Timestamp > ago(win) | where ThreatTypes has_any ('Phish','Malware') | summarize ['Malicious Clicks']=count(), ['Last Click']=max(Timestamp) by UPN = tolower(AccountUpn);
phishClickers
| join kind=inner riskySignIn on UPN
| project UPN, ['Malicious Clicks'], ['Risky Sign-Ins'], ['Max Risk'], ['Last Click']
| order by ['Malicious Clicks'] desc, ['Risky Sign-Ins'] desc
| take 20

let win = totimespan({Window});
let delivered = EmailEvents | where Timestamp > ago(win) | where EmailDirection == 'Inbound' | where ThreatTypes has_any ('Phish','Malware') | where DeliveryLocation in ('Inbox/folder','Junk folder') | project NetworkMessageId, DeliveredAt = Timestamp;
let zap = EmailPostDeliveryEvents | where Timestamp > ago(win) | where ActionType has_any ('ZAP','Zap','Phish','Malware') | summarize ZapAt = min(Timestamp) by NetworkMessageId;
let joined = delivered | join kind=inner zap on NetworkMessageId | extend MTTR_min = datetime_diff('minute', ZapAt, DeliveredAt) | where MTTR_min between (0 .. (60*24*7));
let remediated = tolong(coalesce(toscalar(joined | summarize count()), 0));
let deliveredCount = tolong(coalesce(toscalar(delivered | summarize dcount(NetworkMessageId)), 0));
let bypass = deliveredCount - remediated;
let p50 = tolong(coalesce(toscalar(joined | summarize percentile(MTTR_min, 50)), 0));
let p90 = tolong(coalesce(toscalar(joined | summarize percentile(MTTR_min, 90)), 0));
union
 (print Order=1, Metric='♻️ Threats remediated by ZAP', Value=tolong(remediated), Sub=strcat(tostring(toint(round(100.0*remediated/iff(deliveredCount==0,1,deliveredCount),0))), '% of delivered threats')),
 (print Order=2, Metric='🔴 Bypass cases (NOT remediated)', Value=tolong(bypass), Sub='delivered AND not removed by ZAP'),
 (print Order=3, Metric='⏱️ ZAP MTTR p50', Value=tolong(p50), Sub='median minutes from delivery to remediation'),
 (print Order=4, Metric='⏱️ ZAP MTTR p90', Value=tolong(p90), Sub='90th percentile (minutes)')
| project Order, Metric, Value, Sub
| order by Order asc

let win = totimespan({Window});
let delivered = EmailEvents | where Timestamp > ago(win) | where EmailDirection == 'Inbound' | where ThreatTypes has_any ('Phish','Malware') | where DeliveryLocation in ('Inbox/folder','Junk folder');
let remediatedIds = toscalar(EmailPostDeliveryEvents | where Timestamp > ago(win) | where ActionType has_any ('ZAP','Zap','Phish','Malware') | summarize make_set(NetworkMessageId));
delivered
| where NetworkMessageId !in (remediatedIds)
| project Timestamp, SenderFromAddress, RecipientEmailAddress, Subject, ThreatTypes, DeliveryLocation, DetectionMethods
| order by Timestamp desc
| take 25

let win = totimespan({Window});
let u = Usage | where TimeGenerated > ago(win) | where IsBillable == true;
let totals = u | summarize TotalGB = round(sum(Quantity)/1024.0, 1), Tables = dcount(DataType), Days = dcount(bin(StartTime,1d));
let peak = u | summarize GB = sum(Quantity)/1024.0 by bin(StartTime, 1d) | top 1 by GB desc;
union
  (totals | project Metric = '1 · Total billable GB', Value = TotalGB),
  (totals | project Metric = '2 · Avg GB / day', Value = round(TotalGB/todouble(Days), 2)),
  (totals | project Metric = '3 · Tables ingesting', Value = todouble(Tables)),
  (peak   | project Metric = '4 · Peak day GB', Value = round(GB, 1))
| project Metric, Value
| order by Metric asc
